    pub const @"WITH admission_selection AS (SELECT m.session_ref FROM message_admission m @index(message_admission_pending) WHERE @served((SELECT provider FROM session WHERE session_ref=m.session_ref)) AND m.turn_id IS NULL AND NOT (EXISTS(SELECT 1 FROM session_stop source_stop WHERE source_stop.session_ref=m.session_ref AND m.admission_id<=source_stop.admission_cutoff) OR EXISTS(SELECT 1 FROM session_stop_owed owed WHERE owed.child_ref=m.session_ref AND owed.settled=0)) AND (NOT EXISTS( SELECT 1 FROM turn active WHERE active.session_ref=m.session_ref AND active.outcome_code IS NULL) OR EXISTS( SELECT 1 FROM turn active JOIN model_operation current ON current.operation_id=active.operation_id AND current.session_ref=active.session_ref  WHERE active.session_ref=m.session_ref AND active.outcome_code IS NULL  AND ((current.resolution_code='answer' OR current.resolution_code='compacted' OR current.resolution_code='interrupted' OR current.resolution_code='context_overflow') OR (current.resolution_code='tool_proposals' AND EXISTS( SELECT 1 FROM model_output_item item WHERE item.operation_id=current.operation_id AND item.item_ordinal>=0 AND item.session_ref=current.session_ref AND item.item_kind=3) AND (SELECT count(*) FROM model_tool_call tool_call WHERE tool_call.operation_id=current.operation_id AND tool_call.session_ref=current.session_ref)=( SELECT count(*) FROM model_output_item item WHERE item.operation_id=current.operation_id AND item.item_ordinal>=0 AND item.session_ref=current.session_ref AND item.item_kind=3) AND NOT EXISTS( SELECT 1 FROM model_output_item item LEFT JOIN model_tool_call tool_call  ON tool_call.operation_id=item.operation_id AND tool_call.session_ref=item.session_ref AND tool_call.item_ordinal=item.item_ordinal  LEFT JOIN action_operation action ON action.parent_operation_id=tool_call.operation_id  AND action.session_ref=tool_call.session_ref AND action.call_ordinal=tool_call.call_ordinal WHERE item.operation_id=current.operation_id AND item.item_ordinal>=0 AND item.session_ref=current.session_ref AND item.item_kind=3 AND tool_call.rejection_code IS NULL AND coalesce(action.background_position,action.acceptance_position) IS NULL))))) ORDER BY m.admission_id LIMIT 1),context_session AS (SELECT s.session_ref,s.next_position AS boundary,s.provider,s.model FROM session s JOIN admission_selection chosen ON chosen.session_ref=s.session_ref),base AS (SELECT candidate.operation_id,candidate.admission_position,candidate.history_floor,candidate.session_ref,candidate.settings_revision FROM context_session context JOIN model_operation candidate ON candidate.operation_id=(SELECT selected.operation_id FROM model_operation selected @index(model_operation_compaction_bases) WHERE selected.session_ref=context.session_ref AND selected.purpose=1 AND selected.resolution_code='compacted' AND selected.admission_position<context.boundary ORDER BY selected.admission_position DESC LIMIT 1)),since AS (SELECT NOT EXISTS(SELECT 1 FROM base WHERE NOT EXISTS(SELECT 1 FROM conversation_entry e WHERE e.session_ref=context.session_ref AND e.entry_kind IN (1,2,4) AND e.session_position>base.admission_position AND e.session_position<context.boundary) AND NOT EXISTS(SELECT 1 FROM model_output_item item @index(model_output_history) CROSS JOIN model_operation suffix ON suffix.operation_id=item.operation_id WHERE item.session_ref=context.session_ref AND suffix.session_ref=context.session_ref AND suffix.purpose=0 AND item.session_position>base.admission_position AND item.session_position<context.boundary)) AS changed FROM context_session context),latest_usage AS (SELECT o.history_floor AS usage_floor,o.usage_uncached_tokens AS uncached,o.usage_cache_read_tokens AS cache_read,o.usage_cache_write_tokens AS cache_write,o.usage_output_tokens AS output,coalesce((SELECT max(i.session_position) FROM model_output_item i WHERE i.operation_id=o.operation_id),o.admission_position) AS usage_position,o.admission_position AS result_admission FROM model_operatio